#!/usr/bin/env node
import { pathToFileURL } from 'node:url';
import { sales } from './data.js';
import { formatReport, totals } from './report.js';

export function formatOutput(rows, args) {
  return args.includes('--csv')
    ? ['name,total', ...rows.map(({ name, total }) => `${name},${total.toFixed(2)}`)].join('\n')
    : formatReport(rows);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  console.log(formatOutput(totals(sales), process.argv));
}

